    correction: [{"quoi":"نفكّك العبارة الأولى","math":"<span dir=\"ltr\" class=\"expr\">14n + 14 = 7(2n + 2)</span>"},{"quoi":"نفكّك العبارة الثانية","math":"<span dir=\"ltr\" class=\"expr\">21n + 28 = 7(3n + 4)</span>"},{"quoi":"نستنتج قاسما مشتركا","math":"العدد 7 يقسم العبارتين مهما يكن n"},{"quoi":"نقارن بالتعريف","math":"عددان أوليان فيما بينهما ق.م.أ لهما يساوي 1، و هنا ق.م.أ يقبل القسمة على 7"},{"quoi":"الجواب","math":"خطأ"}],
